<?php $page_title='Categories';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action'];if($a==='save'){try{$id=(int)$_POST['id'];$name=trim($_POST['name']);$desc=trim($_POST['description']);if($id)$pdo->prepare("UPDATE categories SET name=?,description=? WHERE id=?")->execute([$name,$desc,$id]);else$pdo->prepare("INSERT INTO categories(name,description) VALUES(?,?)")->execute([$name,$desc]);flash('success','Category saved.');}catch(PDOException $e){flash('error','Category names must be unique.');}header('Location: categories.php');exit;}if($a==='delete'){$id=(int)$_POST['id'];$n=$pdo->prepare("SELECT COUNT(*) FROM products WHERE category_id=?");$n->execute([$id]);if($n->fetchColumn()>0)flash('error','Cannot delete a category used by products.');else{$pdo->prepare("DELETE FROM categories WHERE id=?")->execute([$id]);flash('success','Category deleted.');}header('Location: categories.php');exit;}}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM categories WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=$pdo->query("SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();?>
<div class="page-head"><div><h1>Categories</h1><p>Control shop filters and catalog grouping.</p></div><a class="btn" href="?edit=0">+ Add category</a></div><?php if($edit!==null):?><div class="panel" style="margin-bottom:18px"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="form-grid"><div class="field"><label>Name</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" required></div><div class="field"><label>Description</label><input class="input" name="description" value="<?=e($edit['description']??'')?>"></div></div><button class="btn">Save</button> <a class="btn light" href="categories.php">Cancel</a></form></div><?php endif;?><div class="panel"><div class="table-wrap"><table><tr><th>Name</th><th>Description</th><th>Products</th><th>Actions</th></tr><?php foreach($cats as $c):?><tr><td><strong><?=e($c['name'])?></strong></td><td><?=e($c['description'])?></td><td><?=$c['product_count']?></td><td><a class="btn light" href="?edit=<?=$c['id']?>">Edit</a> <form class="inline" style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn danger" data-confirm="Are you sure you want to delete this category?">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
